+				<td><a href="' . $SelfURL . '?StockID=' . urlencode($StockID) . '&amp;Edit=' . $MyRow['noteid'] . '">' . __('Edit') . '</a></td>
+				<td><a href="' . $SelfURL . '?StockID=' . urlencode($StockID) . '&amp;Delete=' . $MyRow['noteid'] . '" onclick="return confirm(\'' . __('Are you sure you wish to delete this note?') . '\');">' . __('Delete') . '</a></td>
+			</tr>';
+	}
+	echo '</tbody></table>';
+} else {
+	prnMsg(__('There are no notes for this item'), 'info');
+}
+
+// Add / edit form
+echo '<form method="post" action="' . $SelfURL . '">
+	<div>
+	<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />
+	<input type="hidden" name="StockID" value="' . htmlspecialchars($StockID, ENT_QUOTES, 'UTF-8') . '" />
