+	<fieldset>
+		<legend>' . ($NoteID > 0 ? __('Edit Note') : __('New Note')) . '</legend>
+		<field>
+			<label for="Note">' . __('Note') . ':</label>
+			<textarea name="Note" id="Note" cols="60" rows="5" required="required">' . $EditNote . '</textarea>
+		</field>
+	</fieldset>
+	<div class="centre">
+		<input type="submit" name="submit" value="' . ($NoteID > 0 ? __('Update Note') : __('Add Note')) . '" />';
+if ($NoteID > 0) {
+	echo ' <a href="' . $SelfURL . '?StockID=' . urlencode($StockID) . '">' . __('Cancel') . '</a>';
+}
+echo '</div>
+	</div>
+	</form>';
+
+include('includes/footer.php');
