+			if ($TestRow[0] == 0) {
+				$InputError = 1;
+				prnMsg(__('Stock item') . ' ' . htmlspecialchars($StockID, ENT_QUOTES, 'UTF-8') . ' ' . __('does not exist'), 'error');
+			}
+		}
+		if ($Note == '') {
+			$InputError = 1;
+			prnMsg(__('The note cannot be empty'), 'error');
+		}
+
+		if ($InputError != 1) {
+			$SQL = "INSERT INTO stockitemnotes (stockid, note, userid, dateadded)
+					VALUES ('" . DB_escape_string($StockID) . "',
+							'" . DB_escape_string(htmlspecialchars($Note, ENT_QUOTES, 'UTF-8')) . "',
+							'" . $_SESSION['UserID'] . "',
+							'" . date('Y-m-d H:i:s') . "')";
+			DB_query($SQL, __('The note could not be added because'));
+			$NotesAdded++;
+		}
+
+		if ($InputError == 1) {
+			break;
+		}
+		$Row++;
+	}
+
+	if ($InputError == 1) {
+		prnMsg(__('Failed on row ' . $Row . '. Batch import has been rolled back.'), 'error');
+		DB_Txn_Rollback();
+	} else {
+		DB_Txn_Commit();
+		prnMsg(__('Batch Import of') . ' ' . htmlspecialchars($FileName, ENT_QUOTES, 'UTF-8') . ' ' . __('has been completed') . ': ' . $NotesAdded . ' ' . __('notes added') . '.', 'success');
+	}
+
+	fclose($FileHandle);
+
+} elseif (isset($_POST['gettemplate']) || isset($_GET['gettemplate'])) { //download an import template
+
+	echo '<br /><br /><br />"' . implode('","', $FieldHeadings) . '"<br /><br /><br />';
+
+} else { //show file upload form
+
+	echo '
+		<br />
+		<a href="' . $RootPath . '/Z_ImportStockNotes.php?gettemplate=1">' . __('Get Import Template') . '</a>
+		<br />

