188:+		__('Import Stock Item Notes from .csv') . '</p>';
189:+
190:+// If this script is called with a file object, then the file contents are imported
191:+// If this script is called with the gettemplate flag, then a template file is served
192:+// Otherwise, a file upload form is displayed
193:+
194:+// One note per row; an item with several notes has several rows. Items must already exist
195:+// (import them with Z_ImportStocks.php first). Existing notes are never changed or removed.
196:+
197:+$FieldHeadings = array(
198:+	'StockID',	// 0
199:+	'Note'		// 1
200:+);
201:+
202:+if (isset($_FILES['userfile']) and $_FILES['userfile']['name']) { //start file processing
203:+
204:+	$FieldTarget = count($FieldHeadings);
205:+	$InputError = 0;
206:+
207:+	$FileName = $_FILES['userfile']['name'];
208:+	$TempName = $_FILES['userfile']['tmp_name'];
209:+
210:+	$FileHandle = fopen($TempName, 'r');
211:+
212:+	$HeadRow = fgetcsv($FileHandle, 10000, ",", '"');
213:+	// Remove UTF-8 BOM if present
214:+	if (substr($HeadRow[0], 0, 3) === "\xef\xbb\xbf") {
215:+		$HeadRow[0] = substr($HeadRow[0], 3);
216:+	}
217:+
218:+	if (count($HeadRow) != $FieldTarget) {
219:+		prnMsg(__('File contains ' . count($HeadRow) . ' columns, expected ' . $FieldTarget . '. Try downloading a new template.'), 'error');
220:+		fclose($FileHandle);
221:+		include('includes/footer.php');
222:+		exit();
223:+	}
224:+
225:+	foreach ($HeadRow as $Head => $HeadField) {
226:+		if (mb_strtoupper(trim($HeadField)) != mb_strtoupper($FieldHeadings[$Head])) {
227:+			prnMsg(__('File contains incorrect headers ' . mb_strtoupper($HeadField) . ' != ' . mb_strtoupper($FieldHeadings[$Head]) . '. Try downloading a new template.'), 'error');
228:+			fclose($FileHandle);
229:+			include('includes/footer.php');
230:+			exit();
231:+		}
232:+	}
233:+
234:+	DB_Txn_Begin();
235:+
236:+	$Row = 1;
237:+	$NotesAdded = 0;
238:+	while (($MyRow = fgetcsv($FileHandle, 10000, ",", '"')) !== false) {
239:+
240:+		if ($MyRow === array(null)) { // blank line
