258:+			$TestRow = DB_fetch_row($Result);
259:+			if ($TestRow[0] == 0) {
260:+				$InputError = 1;
261:+				prnMsg(__('Stock item') . ' ' . htmlspecialchars($StockID, ENT_QUOTES, 'UTF-8') . ' ' . __('does not exist'), 'error');
262:+			}
263:+		}
264:+		if ($Note == '') {
265:+			$InputError = 1;
266:+			prnMsg(__('The note cannot be empty'), 'error');
267:+		}
268:+
269:+		if ($InputError != 1) {
270:+			$SQL = "INSERT INTO stockitemnotes (stockid, note, userid, dateadded)
271:+					VALUES ('" . DB_escape_string($StockID) . "',
272:+							'" . DB_escape_string(htmlspecialchars($Note, ENT_QUOTES, 'UTF-8')) . "',
273:+							'" . $_SESSION['UserID'] . "',
274:+							'" . date('Y-m-d H:i:s') . "')";
275:+			DB_query($SQL, __('The note could not be added because'));
276:+			$NotesAdded++;
277:+		}
278:+
279:+		if ($InputError == 1) {
280:+			break;
281:+		}
282:+		$Row++;
283:+	}
284:+
285:+	if ($InputError == 1) {
286:+		prnMsg(__('Failed on row ' . $Row . '. Batch import has been rolled back.'), 'error');
287:+		DB_Txn_Rollback();
288:+	} else {
289:+		DB_Txn_Commit();
290:+		prnMsg(__('Batch Import of') . ' ' . htmlspecialchars($FileName, ENT_QUOTES, 'UTF-8') . ' ' . __('has been completed') . ': ' . $NotesAdded . ' ' . __('notes added') . '.', 'success');
