301:+	echo '
302:+		<br />
303:+		<a href="' . $RootPath . '/Z_ImportStockNotes.php?gettemplate=1">' . __('Get Import Template') . '</a>
304:+		<br />
305:+		<br />';
306:+	echo '<form action="' . htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '" method="post" enctype="multipart/form-data">';
307:+	echo '<div class="centre">';
308:+	echo '<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />';
309:+
310:+	echo '<input type="hidden" name="MAX_FILE_SIZE" value="1000000" />' .
