170:diff --git a/Z_ImportStockNotes.php b/Z_ImportStockNotes.php
173:--- /dev/null
174:+++ b/Z_ImportStockNotes.php
175:@@ -0,0 +1,143 @@
176:+<?php
177:+
178:+require(__DIR__ . '/includes/session.php');
179:+
180:+$Title = __('Import Item Notes');
181:+$ViewTopic = 'SpecialUtilities';
182:+$BookMark = basename(__FILE__, '.php');
183:+include('includes/header.php');
184:+
185:+echo '<p class="page_title_text"><img alt="" src="' . $RootPath . '/css/' . $Theme .
186:+		'/images/inventory.png" title="' .
187:+		__('Import Stock Item Notes from .csv') . '" />' . ' ' .
188:+		__('Import Stock Item Notes from .csv') . '</p>';
189:+
190:+// If this script is called with a file object, then the file contents are imported
191:+// If this script is called with the gettemplate flag, then a template file is served
192:+// Otherwise, a file upload form is displayed
193:+
194:+// One note per row; an item with several notes has several rows. Items must already exist
195:+// (import them with Z_ImportStocks.php first). Existing notes are never changed or removed.
196:+
197:+$FieldHeadings = array(
198:+	'StockID',	// 0
199:+	'Note'		// 1
200:+);
201:+
202:+if (isset($_FILES['userfile']) and $_FILES['userfile']['name']) { //start file processing
203:+
204:+	$FieldTarget = count($FieldHeadings);
205:+	$InputError = 0;
206:+
207:+	$FileName = $_FILES['userfile']['name'];
208:+	$TempName = $_FILES['userfile']['tmp_name'];
209:+
210:+	$FileHandle = fopen($TempName, 'r');
211:+
212:+	$HeadRow = fgetcsv($FileHandle, 10000, ",", '"');
213:+	// Remove UTF-8 BOM if present
214:+	if (substr($HeadRow[0], 0, 3) === "\xef\xbb\xbf") {
215:+		$HeadRow[0] = substr($HeadRow[0], 3);
216:+	}
217:+
218:+	if (count($HeadRow) != $FieldTarget) {
219:+		prnMsg(__('File contains ' . count($HeadRow) . ' columns, expected ' . $FieldTarget . '. Try downloading a new template.'), 'error');
220:+		fclose($FileHandle);
221:+		include('includes/footer.php');
222:+		exit();
223:+	}
224:+
225:+	foreach ($HeadRow as $Head => $HeadField) {
226:+		if (mb_strtoupper(trim($HeadField)) != mb_strtoupper($FieldHeadings[$Head])) {
227:+			prnMsg(__('File contains incorrect headers ' . mb_strtoupper($HeadField) . ' != ' . mb_strtoupper($FieldHeadings[$Head]) . '. Try downloading a new template.'), 'error');
228:+			fclose($FileHandle);
229:+			include('includes/footer.php');
230:+			exit();
231:+		}
232:+	}
233:+
234:+	DB_Txn_Begin();
235:+
236:+	$Row = 1;
237:+	$NotesAdded = 0;
238:+	while (($MyRow = fgetcsv($FileHandle, 10000, ",", '"')) !== false) {
239:+
240:+		if ($MyRow === array(null)) { // blank line
241:+			continue;
242:+		}
243:+
244:+		if (count($MyRow) != $FieldTarget) {
245:+			prnMsg(__($FieldTarget . ' fields required, ' . count($MyRow) . ' fields received'), 'error');
246:+			$InputError = 1;
247:+			break;
248:+		}
249:+
250:+		$StockID = mb_strtoupper(trim($MyRow[0]));
251:+		$Note = trim($MyRow[1]);
252:+
253:+		if ($StockID == '') {
254:+			$InputError = 1;
255:+			prnMsg(__('The Stock Item code cannot be empty'), 'error');
256:+		} else {
257:+			$Result = DB_query("SELECT COUNT(stockid) FROM stockmaster WHERE stockid='" . DB_escape_string($StockID) . "'");
258:+			$TestRow = DB_fetch_row($Result);
259:+			if ($TestRow[0] == 0) {
260:+				$InputError = 1;
261:+				prnMsg(__('Stock item') . ' ' . htmlspecialchars($StockID, ENT_QUOTES, 'UTF-8') . ' ' . __('does not exist'), 'error');
262:+			}
263:+		}
264:+		if ($Note == '') {
265:+			$InputError = 1;
266:+			prnMsg(__('The note cannot be empty'), 'error');
267:+		}
268:+
269:+		if ($InputError != 1) {
270:+			$SQL = "INSERT INTO stockitemnotes (stockid, note, userid, dateadded)
271:+					VALUES ('" . DB_escape_string($StockID) . "',
272:+							'" . DB_escape_string(htmlspecialchars($Note, ENT_QUOTES, 'UTF-8')) . "',
273:+							'" . $_SESSION['UserID'] . "',
274:+							'" . date('Y-m-d H:i:s') . "')";
275:+			DB_query($SQL, __('The note could not be added because'));
276:+			$NotesAdded++;
277:+		}
278:+
279:+		if ($InputError == 1) {
280:+			break;
281:+		}
282:+		$Row++;
283:+	}
284:+
285:+	if ($InputError == 1) {
286:+		prnMsg(__('Failed on row ' . $Row . '. Batch import has been rolled back.'), 'error');
287:+		DB_Txn_Rollback();
288:+	} else {
289:+		DB_Txn_Commit();
290:+		prnMsg(__('Batch Import of') . ' ' . htmlspecialchars($FileName, ENT_QUOTES, 'UTF-8') . ' ' . __('has been completed') . ': ' . $NotesAdded . ' ' . __('notes added') . '.', 'success');
291:+	}
292:+
293:+	fclose($FileHandle);
294:+
295:+} elseif (isset($_POST['gettemplate']) || isset($_GET['gettemplate'])) { //download an import template
296:+
297:+	echo '<br /><br /><br />"' . implode('","', $FieldHeadings) . '"<br /><br /><br />';
298:+
299:+} else { //show file upload form
300:+
301:+	echo '
302:+		<br />
303:+		<a href="' . $RootPath . '/Z_ImportStockNotes.php?gettemplate=1">' . __('Get Import Template') . '</a>
304:+		<br />
305:+		<br />';
306:+	echo '<form action="' . htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '" method="post" enctype="multipart/form-data">';
307:+	echo '<div class="centre">';
308:+	echo '<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />';
309:+
310:+	echo '<input type="hidden" name="MAX_FILE_SIZE" value="1000000" />' .
311:+			__('Upload file') . ': <input name="userfile" type="file" />
312:+			<input type="submit" value="' . __('Send File') . '" />
313:+		</div>
314:+		</form>';
315:+
316:+}
317:+
318:+include('includes/footer.php');
